const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Lake Elton geometry (Russia)
  const lakeElton = ee.Geometry.Point([46.68, 49.15]).buffer(5000);

  // 2. Cloud masking function for Landsat Collection 2
  function maskClouds(image) {
    const qa = image.select('QA_PIXEL');
    const cloudMask = qa.bitwiseAnd(1 << 3).eq(0)
      .and(qa.bitwiseAnd(1 << 4).eq(0));
    return image.updateMask(cloudMask);
  }

  // 3. Get Landsat 5 data for 2004
  let col2004 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(lakeElton)
    .filterDate('2004-01-01', '2004-12-31')
    .map(maskClouds);

  const size2004 = col2004.size().getInfo();
  console.log(`2004 Images: ${size2004}`);

  if (size2004 === 0) {
    console.log('No data for 2004.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Get Landsat 5 data for 2009
  let col2009 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(lakeElton)
    .filterDate('2009-01-01', '2009-12-31')
    .map(maskClouds);

  const size2009 = col2009.size().getInfo();
  console.log(`2009 Images: ${size2009}`);

  if (size2009 === 0) {
    console.log('No data for 2009.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Calculate median composite and surface reflectance
  const img2004 = col2004.median();
  const img2009 = col2009.median();

  // Use NIR band (SR_B4) for surface reflectance comparison
  const band = 'SR_B4';

  // 6. Check pixel counts
  const count2004 = img2004.select(band).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeElton,
    scale: 1000,
    maxPixels: 1e9
  }).get(band).getInfo();

  const count2009 = img2009.select(band).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeElton,
    scale: 1000,
    maxPixels: 1e9
  }).get(band).getInfo();

  console.log(`2004 Valid Pixels: ${count2004}`);
  console.log(`2009 Valid Pixels: ${count2009}`);

  if (count2004 === 0 || count2009 === 0) {
    console.log('No valid pixels after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 7. Calculate mean surface reflectance
  const refl2004 = img2004.select(band).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: lakeElton,
    scale: 1000,
    maxPixels: 1e9
  }).get(band).getInfo();

  const refl2009 = img2009.select(band).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: lakeElton,
    scale: 1000,
    maxPixels: 1e9
  }).get(band).getInfo();

  console.log(`2004 Mean Reflectance: ${refl2004}`);
  console.log(`2009 Mean Reflectance: ${refl2009}`);

  // 8. Validation and final answer
  if (refl2004 === null || refl2009 === null || 
      isNaN(refl2004) || isNaN(refl2009)) {
    console.log('Calculation failed.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Check if values are in valid range (Landsat scaled: 0-65535)
  if (refl2004 < 0 || refl2009 < 0 || refl2004 > 65535 || refl2009 > 65535) {
    console.log('Invalid reflectance values.');
    console.log('<answer>C3</answer>');
    return;
  }

  const change = refl2009 - refl2004;
  console.log(`Change: ${change.toFixed(2)}`);

  if (change > 0) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
